/**
 * QuizLens AI - Popup Script
 * Handles configuration UI and testing connection
 */

import { DEFAULT_SETTINGS, PROVIDER_MODELS } from '../shared/constants';
import { ExtensionSettings, ProviderType } from '../shared/types';

document.addEventListener('DOMContentLoaded', () => {
  const enabledToggle = document.getElementById('enabledToggle') as HTMLInputElement;
  const backendUrlInput = document.getElementById('backendUrl') as HTMLInputElement;
  const providerSelect = document.getElementById('providerSelect') as HTMLSelectElement;
  const modelSelect = document.getElementById('modelSelect') as HTMLSelectElement;
  const apiKeyInput = document.getElementById('apiKeyInput') as HTMLInputElement;
  const toggleApiKeyVisBtn = document.getElementById('toggleApiKeyVis') as HTMLButtonElement;
  const autoCopyToggle = document.getElementById('autoCopyToggle') as HTMLInputElement;
  const testBtn = document.getElementById('testBtn') as HTMLButtonElement;
  const saveBtn = document.getElementById('saveBtn') as HTMLButtonElement;
  const statusBadge = document.getElementById('statusBadge') as HTMLDivElement;
  const feedbackMsg = document.getElementById('feedbackMsg') as HTMLDivElement;
  const keyHint = document.getElementById('keyHint') as HTMLSpanElement;

  let currentSettings: ExtensionSettings = { ...DEFAULT_SETTINGS };

  // Update Model dropdown based on Provider
  function updateModelOptions(provider: string, selectedModel?: string) {
    const models = PROVIDER_MODELS[provider] || [];
    modelSelect.innerHTML = '';
    models.forEach((m) => {
      const opt = document.createElement('option');
      opt.value = m;
      opt.textContent = m;
      if (m === selectedModel) {
        opt.selected = true;
      }
      modelSelect.appendChild(opt);
    });
  }

  // Update API key field placeholder, hint & value based on provider
  function syncApiKeyField(provider: ProviderType) {
    if (provider === 'gemini') {
      apiKeyInput.value = currentSettings.geminiApiKey || '';
      apiKeyInput.placeholder = 'AIzaSy...';
      keyHint.innerHTML = 'Lấy API Key miễn phí tại: <a href="https://aistudio.google.com/app/apikey" target="_blank" style="color: #2563EB; font-weight: 600;">Google AI Studio</a>';
    } else if (provider === 'groq') {
      apiKeyInput.value = currentSettings.groqApiKey || '';
      apiKeyInput.placeholder = 'gsk_...';
      keyHint.innerHTML = 'Lấy API Key miễn phí tại: <a href="https://console.groq.com/keys" target="_blank" style="color: #2563EB; font-weight: 600;">Groq Console</a>';
    } else if (provider === 'openrouter') {
      apiKeyInput.value = currentSettings.openrouterApiKey || '';
      apiKeyInput.placeholder = 'sk-or-...';
      keyHint.innerHTML = 'Lấy API Key miễn phí tại: <a href="https://openrouter.ai/keys" target="_blank" style="color: #2563EB; font-weight: 600;">OpenRouter Keys</a>';
    }

    updateStatusBadge();
  }

  function updateStatusBadge() {
    const key = apiKeyInput.value.trim();
    if (key.length > 5) {
      statusBadge.textContent = 'Key sẵn sàng';
      statusBadge.className = 'status-badge connected';
    } else {
      statusBadge.textContent = 'Chưa có Key';
      statusBadge.className = 'status-badge error';
    }
  }

  // Load settings from Service Worker
  chrome.runtime.sendMessage({ type: 'GET_SETTINGS' }, (response) => {
    if (response?.success && response.data) {
      currentSettings = { ...DEFAULT_SETTINGS, ...response.data };

      enabledToggle.checked = currentSettings.enabled;
      backendUrlInput.value = currentSettings.backendUrl;
      providerSelect.value = currentSettings.activeProvider;
      autoCopyToggle.checked = currentSettings.autoCopy;

      const activeModel =
        currentSettings.activeProvider === 'gemini'
          ? currentSettings.geminiModel
          : currentSettings.activeProvider === 'groq'
          ? currentSettings.groqModel
          : currentSettings.openrouterModel;

      updateModelOptions(currentSettings.activeProvider, activeModel);
      syncApiKeyField(currentSettings.activeProvider);
    }
  });

  // Handle Provider Change
  providerSelect.addEventListener('change', () => {
    const provider = providerSelect.value as ProviderType;
    currentSettings.activeProvider = provider;
    updateModelOptions(provider);
    syncApiKeyField(provider);
  });

  apiKeyInput.addEventListener('input', () => {
    updateStatusBadge();
  });

  // Toggle API key visibility
  let isKeyVisible = false;
  toggleApiKeyVisBtn.addEventListener('click', () => {
    isKeyVisible = !isKeyVisible;
    apiKeyInput.type = isKeyVisible ? 'text' : 'password';
    toggleApiKeyVisBtn.textContent = isKeyVisible ? 'Ẩn' : 'Hiện';
  });

  // Test Connection
  testBtn.addEventListener('click', () => {
    const key = apiKeyInput.value.trim();
    if (key.length > 5) {
      statusBadge.textContent = 'Sẵn sàng';
      statusBadge.className = 'status-badge connected';
      showFeedback('API Key đã được cấu hình và sẵn sàng hoạt động trực tiếp!', 'success');
      return;
    }

    statusBadge.textContent = 'Đang kiểm tra...';
    statusBadge.className = 'status-badge';
    feedbackMsg.textContent = '';

    const targetUrl = backendUrlInput.value.trim() || DEFAULT_SETTINGS.backendUrl;
    chrome.runtime.sendMessage(
      { type: 'TEST_CONNECTION', payload: { backendUrl: targetUrl } },
      (res) => {
        if (res?.success) {
          statusBadge.textContent = 'Kết nối OK';
          statusBadge.className = 'status-badge connected';
          showFeedback('Đã kết nối với máy chủ!', 'success');
        } else {
          statusBadge.textContent = 'Chưa có Key';
          statusBadge.className = 'status-badge error';
          showFeedback('Vui lòng dán API Key để sử dụng trực tiếp!', 'error');
        }
      }
    );
  });

  // Save Settings
  saveBtn.addEventListener('click', () => {
    const activeProvider = providerSelect.value as ProviderType;
    const selectedModel = modelSelect.value;
    const apiKey = apiKeyInput.value.trim();

    const updated: Partial<ExtensionSettings> = {
      enabled: enabledToggle.checked,
      backendUrl: backendUrlInput.value.trim() || DEFAULT_SETTINGS.backendUrl,
      activeProvider,
      autoCopy: autoCopyToggle.checked
    };

    if (activeProvider === 'gemini') {
      updated.geminiModel = selectedModel;
      updated.geminiApiKey = apiKey;
    } else if (activeProvider === 'groq') {
      updated.groqModel = selectedModel;
      updated.groqApiKey = apiKey;
    } else if (activeProvider === 'openrouter') {
      updated.openrouterModel = selectedModel;
      updated.openrouterApiKey = apiKey;
    }

    chrome.runtime.sendMessage({ type: 'SAVE_SETTINGS', payload: updated }, (res) => {
      if (res?.success) {
        currentSettings = { ...currentSettings, ...updated };
        updateStatusBadge();
        showFeedback('Đã lưu cấu hình thành công!', 'success');
      } else {
        showFeedback('Lỗi khi lưu cấu hình.', 'error');
      }
    });
  });

  function showFeedback(text: string, type: 'success' | 'error') {
    feedbackMsg.textContent = text;
    feedbackMsg.className = `feedback-msg ${type}`;
    setTimeout(() => {
      if (feedbackMsg.textContent === text) {
        feedbackMsg.textContent = '';
      }
    }, 3000);
  }
});
